use crate::{files::{args,path,text,write_text},text_tools::{all_files,read_string,boolean}};
use serde_json::{json,Value};
use std::{collections::BTreeMap,fs,path::{Component,Path,PathBuf}};
pub fn home()->PathBuf{if let Some(h)=std::env::var_os("TELEOPERATOR_HOME"){let p=PathBuf::from(h);if p.is_absolute(){p}else{std::env::current_dir().unwrap_or_default().join(p)}}else{PathBuf::from(std::env::var_os("HOME").unwrap_or_default()).join(".teleoperator")}}
fn relative(s:&str)->Result<PathBuf,String>{let p=Path::new(s);if s.is_empty()||p.components().any(|c|!matches!(c,Component::Normal(_))){return Err("Only safe relative path components allowed".into());}Ok(p.into())}
const MAX_SKILL_PARTS:usize=16;
const MAX_SKILL_LEN:usize=256;
fn component(s:&str)->bool{!s.is_empty()&&s.len()<=64&&!s.contains('\0')}
fn name(s:&str)->Result<&str,String>{if s.len()>64||!s.bytes().all(|b|b.is_ascii_lowercase()||b.is_ascii_digit()||b==b'-'||b==b'_')||s.is_empty(){return Err("Skill name must use lowercase letters, digits, hyphen or underscore (max 64)".into());}Ok(s)}
fn skill_ref(s:&str)->Result<&str,String>{if s.is_empty()||s.len()>MAX_SKILL_LEN||s.contains('\0'){return Err("Skill name must be a relative path of safe components".into());}let mut count=0usize;for c in Path::new(s).components(){match c{Component::Normal(part)=>{let part=part.to_string_lossy();if !component(&part){return Err("Skill name must be a relative path of safe components".into());}count+=1;} _=>return Err("Only safe relative path components allowed".into()),}}if count==0||count>MAX_SKILL_PARTS{return Err("Skill name must be a relative path of safe components".into());}Ok(s)}
fn no_symlinks(p:&Path)->Result<(),String>{let p=path(&p.to_string_lossy())?;let mut current=PathBuf::new();for c in p.components(){current.push(c);match fs::symlink_metadata(&current){Ok(m)if m.file_type().is_symlink()=>return Err("Symlinks are not allowed in skill paths".into()),Ok(_)=>{},Err(e)if e.kind()==std::io::ErrorKind::NotFound=>{},Err(e)=>return Err(e.to_string())}}Ok(())}
fn roots()->Vec<PathBuf>{let mut roots=vec![home().join("skills")];if let Some(h)=std::env::var_os("HOME"){let p=PathBuf::from(h).join(".hermes/skills");if p.exists()&&!roots.contains(&p){roots.push(p);}}roots}
fn rel_key(root:&Path,dir:&Path)->Option<String>{let rel=dir.strip_prefix(root).ok()?;let mut parts=Vec::new();for c in rel.components(){let Component::Normal(s)=c else{return None;};let s=s.to_string_lossy();if !component(&s){return None;}parts.push(s.into_owned());}if parts.is_empty()||parts.len()>MAX_SKILL_PARTS{return None;}let key=parts.join("/");if key.len()>MAX_SKILL_LEN{None}else{Some(key)}}
fn installed()->Result<BTreeMap<String,PathBuf>,String>{let mut found=BTreeMap::new();for r in roots(){if !r.exists(){continue;}no_symlinks(&r)?;for p in all_files(&r)?{if p.file_name().map(|n|n=="SKILL.md").unwrap_or(false){let Some(dir)=p.parent()else{continue;};let Some(key)=rel_key(&r,dir)else{continue;};found.entry(key).or_insert(p);}}}Ok(found)}
fn lookup(n:&str)->Result<(&str,bool),String>{if let Some(rest)=n.strip_prefix("./"){skill_ref(rest)?;return Ok((rest,true));}skill_ref(n)?;Ok((n,false))}
fn resolve(map:&BTreeMap<String,PathBuf>,n:&str,exact:bool)->Result<Option<(String,PathBuf)>,String>{if exact||n.contains('/'){return Ok(map.get(n).map(|p|(n.to_string(),p.clone())));}let mut matches:Vec<_>=map.iter().filter(|(k,_)|k.rsplit('/').next()==Some(n)).collect();matches.sort_by(|a,b|a.0.cmp(b.0));match matches.len(){0=>Ok(None),1=>Ok(Some((matches[0].0.clone(),matches[0].1.clone()))),_=>{let listed=matches.iter().map(|(k,_)|k.as_str()).collect::<Vec<_>>().join(", ");let root=if matches.iter().any(|(k,_)|k.as_str()==n){format!("; ./{n} selects the root skill")}else{String::new()};Err(format!("Ambiguous skill name: {n}; use {listed}{root}"))}}}
fn locate(n:&str,created:&[(String,PathBuf)])->Result<(String,PathBuf),String>{let(query,exact)=lookup(n)?;let mut map=installed()?;for(key,dir)in created{map.insert(key.clone(),dir.join("SKILL.md"));}resolve(&map,query,exact)?.ok_or_else(||format!("Unknown skill: {n}"))}
fn description(s:&str)->String{s.lines().find_map(|l|l.strip_prefix("description:").map(|s|s.trim().trim_matches('"').trim_matches('\'').to_string())).unwrap_or_default()}
fn supporting(s:&str)->Result<PathBuf,String>{let p=relative(s)?;let first=p.components().next().unwrap().as_os_str();if !["references","templates","scripts","assets"].iter().any(|s|first==*s){return Err("Supporting files must start with references/, templates/, scripts/ or assets/".into());}if p.components().count()<2{return Err("Supporting path must name a file within its directory".into());}Ok(p)}
pub fn tool(which:&str,v:&Value)->Result<Value,String>{match which{
 "skills_list"=>{args(v,&["category"])?;let category=v.get("category").filter(|x|!x.is_null()).map(|x|x.as_str().ok_or("category must be string")).transpose()?;let mut skills=Vec::new();for(n,p)in installed()?{if let Some(c)=category{let rel=roots().iter().find_map(|r|p.strip_prefix(r).ok()).map(|p|p.to_string_lossy().into_owned()).unwrap_or_default();if !rel.starts_with(&format!("{c}/"))&&!n.starts_with(&format!("{c}/")){continue;}}let s=read_string(&p)?;skills.push(json!({"name":n,"description":description(&s),"path":p}));}Ok(json!({"skills":skills,"total":skills.len()}))},
 "skill_view"=>{args(v,&["name","file_path"])?;let n=text(v,"name")?;let(key,main)=locate(n,&[])?;let p=if let Some(s)=v.get("file_path").filter(|x|!x.is_null()){main.parent().unwrap().join(supporting(s.as_str().ok_or("file_path must be string")?)?)}else{main.clone()};no_symlinks(&p)?;let content=read_string(&p)?;Ok(json!({"success":true,"name":key,"content":content,"path":p,"skill_dir":main.parent()}))},
 "skill_manage"=>manage(v),_=>Err("Unknown skill tool".into())}}
fn manage(v:&Value)->Result<Value,String>{args(v,&["operations"])?;let ops=v.get("operations").and_then(Value::as_array).ok_or("operations must be an array")?;if ops.is_empty()||ops.len()>100{return Err("operations needs 1..100 entries".into());}let root=path(&home().join("skills").to_string_lossy())?;no_symlinks(&root)?;
 // Validate and stage every operation before changing anything. Only writable-root skills are managed.
 // Identity is the path relative to the skills root, so the same leaf name can exist in two categories.
 let mut staged:BTreeMap<PathBuf,Option<String>>=BTreeMap::new();let mut created:Vec<(String,PathBuf)>=Vec::new();
 for op in ops{let action=text(op,"action")?;let raw=text(op,"name")?;let(key,base)=if action=="create"{let n=name(raw)?;let mut p=root.clone();if let Some(c)=op.get("category"){p=p.join(relative(c.as_str().ok_or("category must be string")?)?);}p=p.join(n);let key=rel_key(&root,&p).ok_or("Invalid skill path")?;(key,p)}else{let(key,md)=locate(raw,&created)?;let base=md.parent().unwrap().to_path_buf();if !base.starts_with(&root){return Err("Read-only fallback skill; management is confined to TELEOPERATOR_HOME/skills".into());}(key,base)};
 let file=if let Some(f)=op.get("file_path"){base.join(supporting(f.as_str().ok_or("file_path must be string")?)?)}else{base.join("SKILL.md")};no_symlinks(&file)?;
 match action{
 "create"=>{args(op,&["action","name","content","category"])?;if base.exists()||created.iter().any(|(existing,_)|existing==&key){return Err("Skill already exists".into());}let content=text(op,"content")?;if !content.starts_with("---\n")||!content.contains("\ndescription:"){return Err("SKILL.md requires YAML frontmatter with description".into());}staged.insert(file,Some(content.into()));created.push((key,base));},
 "patch"=>{args(op,&["action","name","old_string","new_string","replace_all","file_path"])?;let old=text(op,"old_string")?;let new=text(op,"new_string")?;if old.is_empty()||old==new{return Err("old_string must be nonempty and differ from new_string".into());}let content=match staged.get(&file){Some(Some(s))=>s.clone(),Some(None)=>return Err("File has been removed".into()),None=>read_string(&file)?};let count=content.matches(old).count();if count==0||count>1&&!boolean(op,"replace_all")?{return Err(format!("Expected unique match; found {count}"));}staged.insert(file,Some(content.replace(old,new)));},
 "write_file"=>{args(op,&["action","name","file_path","file_content"])?;if !op.get("file_path").is_some(){return Err("file_path is required".into());}staged.insert(file,Some(text(op,"file_content")?.into()));},
 "remove_file"=>{args(op,&["action","name","file_path"])?;if !op.get("file_path").is_some(){return Err("file_path is required".into());}if !file.exists()&&!staged.get(&file).map(|x|x.is_some()).unwrap_or(false){return Err("File does not exist".into());}staged.insert(file,None);},
 _=>return Err(format!("Unsupported skill action: {action}; delete/full replacement are unavailable"))}}
 let mut backups=Vec::new();let mut made_dirs=Vec::new();let result=(||{for(p,content)in &staged{no_symlinks(p)?;let original=if p.exists(){Some(read_string(p)?)}else{None};backups.push((p.clone(),original));if let Some(content)=content{let mut missing=Vec::new();let mut d=p.parent().unwrap();while !d.exists(){missing.push(d.to_path_buf());d=d.parent().ok_or("Missing parent")?;}for d in missing.into_iter().rev(){fs::create_dir(&d).map_err(|e|e.to_string())?;made_dirs.push(d);}crate::files::replace(p,content)?;}else{fs::remove_file(p).map_err(|e|e.to_string())?;}}Ok::<(),String>(())})();if let Err(e)=result{for(p,old)in backups.into_iter().rev(){if let Some(s)=old{let _=write_text(&p,&s);}else{let _=fs::remove_file(&p);}}for d in made_dirs.into_iter().rev(){let _=fs::remove_dir(d);}return Err(e);}Ok(json!({"success":true,"operations":ops.len(),"files_modified":staged.keys().collect::<Vec<_>>()}))}
